//validateIBAN(field_data, row_data)
//
// The International Bank Account Number (IBAN) is an internationally agreed upon system of identifying bank accounts across national borders. 
// international standard ISO 13616 under the International Organization for Standardization (ISO). The current version is ISO 13616:2020,
//
// The IBAN consists of up to 34 alphanumeric characters comprising a country code; two check digits; 
// and a number that includes the domestic bank account number, branch identifier, and potential routing information. 
// The check digits enable a check of the bank account number to confirm its integrity before submitting a transaction.

var mStrMessageError = {
        "ca": "No vàlid",
        "de": "Ungültig",
        "en": "Not valid",
        "es": "No válido",
        "fr": "Non valide",
        "it": "Non valido",
        "pt": "Não válido"
    };

// No data to validate
if (field == null || field.length == 0){
    return true;
}

// When cbancdom.tipacc == 1 then is a BBAN
// If there is no length definition per country
// (iban_length == 0 from field ctiponac.iban = 0) then it always is OK
// Otherwise the bank account must match the predefined length
if (data.cbancdom.tipacc == 1) {
    if (data.ctiponac.iban_lenght == 0 || data.ctiponac.iban_lenght == null || data.ctiponac.iban_lenght == field.length || data.cbancdom.banlen == field.length) {
        return true;
    } else {
       return mStrMessageError[context.lang];;
    }
}

// Minimum length to validate
if (field.length < 5)
    return mStrMessageError[context.lang];;

var CODE_LENGTHS = {
    AL: 28, AD: 24, AT: 20, AZ: 28, BH: 22, BY: 28, BE: 16, BA: 20,
    BR: 29, BG: 22, CR: 22, HR: 21, CY: 28, CZ: 24, DK: 18, DO: 28,
    SV: 28, EE: 20, FO: 18, FI: 18, FR: 27, GE: 22, DE: 22, GI: 23,
    GR: 27, GL: 18, GT: 28, VA: 22, HU: 28, IS: 26, IQ: 23, IE: 22,
    IL: 23, IT: 27, JO: 30, KZ: 20, XK: 20, KW: 30, LV: 21, LB: 28,
    LI: 21, LT: 20, LU: 20, MT: 31, MR: 27, MU: 30, MD: 24, MC: 27,
    ME: 22, NL: 18, MK: 19, NO: 15, PK: 24, PS: 29, PL: 28, PT: 25,
    QA: 29, RO: 24, LC: 32, SM: 27, ST: 25, SA: 24, RS: 22, SC: 31,
    SK: 24, SI: 19, ES: 24, SE: 24, CH: 21, TL: 23, TN: 24, TR: 26,
    UA: 29, AE: 23, GB: 22, VG: 24, DZ: 26, AO: 25, BJ: 28, BF: 28,
    BI: 16, CM: 27, CV: 25, CF: 27, TD: 27, KM: 27, CG: 27, DJ: 27,
    EG: 27, GQ: 27, GA: 27, GW: 25, HN: 28, IR: 26, CI: 28, MG: 27,
    ML: 28, MA: 28, MZ: 25, NI: 32, NE: 28, SN: 28, TG: 28
};

// keep only alphanumeric characters
var iban = String(field).toUpperCase().replace(/[^A-Z0-9]/g, '');

// match and capture (1) the country code, (2) the check digits, and (3) the rest digits
var code = iban.match(/^([A-Z]{2})(\d{2})([A-Z\d]+)$/);
if (code == null)
    return mStrMessageError[context.lang];;

// No country defined return true no validate 
if (!CODE_LENGTHS[code[1]]) {
    return true;
}

// Validate country length.
if (iban.length !== CODE_LENGTHS[code[1]]) {
    return false;
}

// rearrange country code and check digits, and convert chars to ints
var digits = (code[3] + code[1] + code[2]).replace(/[A-Z]/g, function (letter) {
    return letter.charCodeAt(0) - 55;
});

function mod97(string) {
    var checksum = string.slice(0, 2), fragment;
    for (var offset = 2; offset < string.length; offset += 7) {
        fragment = String(checksum) + string.substring(offset, offset + 7);
        checksum = parseInt(fragment, 10) % 97;
    }
    return checksum;
}

// final check
return mod97(digits) == 1;

