/**
 *
 *  validateVAT
 *
 *  Evolution of:
 *    Application: Utility Function
 *    Author:      John Gardner
 *    Website:     http://www.braemoor.co.uk/software/vat.shtml
 */

     // Assume a valid VAT number
     var valid = true;
 
     if (field == null || field == "")
         return valid;
 
     // Assign data
     var mciftyp = data.ciftyp;
     var mcifiss = data.cifiss;

     if (field == data.emp_cif) {
          mciftyp = data.emp_ciftyp;
          mcifiss = data.emp_cifiss;
     }

     //  Only validation in:
     //
     //  0       NIF-Persona física (DNI-NIE)
     //  1       NIF-Empresa Persona jurídica
     //  2       NIF-UE intraCommunity operator
     //  3       Passport
     //  4       DNI
     //
     //  Not validation in:
     //
     //  5       Residence certificate
     //  6       Other
     //  7       Not registered
     if (mciftyp >= 4 || (mciftyp == 0 && mcifiss != 'ES')) {
         return valid;
     }
 
     // Array holds the regular expressions for the valid VAT number
     var vatexp = new Array ();
 
     // To change the default country (e.g. from the UK to Germany - DE):
     //    1.  Change the country code in the defCCode variable below to "DE".
     //    2.  Remove the question mark from the regular expressions associated with the UK VAT number:
     //        i.e. "(GB)?" -> "(GB)"
     //    3.  Add a question mark into the regular expression associated with Germany's number
     //        following the country code: i.e. "(DE)" -> "(DE)?"
 
     // Note - VAT codes without the "**" in the comment do not have check digit checking.
 
     vatexp.push (["AT", /(U\d{8})$/]);                           // ** Austria
     vatexp.push (["AU", /(\d{8})$/]);                            // ** Australia
     // vatexp.push (["BE", /(0?\d{9})$/]);                          // ** Belgium
     vatexp.push (["BE", /^(BE)([0]?\d{9}|[1]\d{9})$/]);			 // ** Belgium	
     vatexp.push (["BG", /(\d{9,10})$/]);                         // ** Bulgaria
     vatexp.push (["CH", /(\d{9})(MWST|TVA|IVA)?$/]);             // ** Switzerland
     vatexp.push (["CY", /([0-59]\d{7}[A-Z])$/]);                 // ** Cyprus
     vatexp.push (["CZ", /(\d{8,10})(\d{3})?$/]);                 // ** Czech Republic
     vatexp.push (["DE", /([1-9]\d{8})$/]);                       // ** Germany
     vatexp.push (["DK", /(\d{8})$/]);                            // ** Denmark
     vatexp.push (["EE", /(10\d{7})$/]);                          // ** Estonia
     vatexp.push (["EL", /(\d{9})$/]);                            // ** Greece
     vatexp.push (["ES", /((ES|)[A-Z]\d{8})$/]);                  // ** Spain (National juridical entities)
     vatexp.push (["ES", /((ES|)[A-HN-SW]\d{7}[A-J])$/]);         // ** Spain (Other juridical entities)
     vatexp.push (["ES", /([0-9YZ]\d{7}[A-Z])$/]);                // ** Spain (Personal entities type 1)
     vatexp.push (["ES", /([KLMXYZ]\d{7}[A-Z])$/]);               // ** Spain (Personal entities type 2)
     vatexp.push (["EU", /(\d{9})$/]);                            // ** EU-type
     vatexp.push (["FI", /(\d{8})$/]);                            // ** Finland
     vatexp.push (["FR", /(\d{11})$/]);                           // ** France (1)
     vatexp.push (["FR", /([A-HJ-NP-Z]\d{10})$/]);                //  France (2)
     vatexp.push (["FR", /(\d[A-HJ-NP-Z]\d{9})$/]);               //  France (3)
     vatexp.push (["FR", /([A-HJ-NP-Z]{2}\d{9})$/]);              //  France (4)
     vatexp.push (["GB", /(\d{9})$/]);                            // ** UK (Standard)
     vatexp.push (["GB", /(\d{12})$/]);                           // ** UK (Branches)
     vatexp.push (["GB", /(GD\d{3})$/]);                          // ** UK (Government)
     vatexp.push (["GB", /(HA\d{3})$/]);                          // ** UK (Health authority)
     vatexp.push (["HR", /(\d{11})$/]);                           // ** Croatia
     vatexp.push (["HU", /(\d{8})$/]);                            // ** Hungary
     vatexp.push (["IE", /(\d{7}[A-W])$/]);                       // ** Ireland (1)
     vatexp.push (["IE", /([7-9][A-Z\*\+)]\d{5}[A-W])$/]);        // ** Ireland (2)
     vatexp.push (["IE", /(\d{7}[A-W][AH])$/]);                   // ** Ireland (3)
     vatexp.push (["IT", /(\d{11})$/]);                           // ** Italy
     vatexp.push (["LV", /(\d{11})$/]);                           // ** Latvia
     vatexp.push (["LT", /(\d{9}|\d{12})$/]);                     // ** Lithunia
     vatexp.push (["LU", /(\d{8})$/]);                            // ** Luxembourg
     vatexp.push (["MT", /([1-9]\d{7})$/]);                       // ** Malta
     vatexp.push (["NL", /(\d{9})B\d{2}$/]);                      // ** Netherlands
     vatexp.push (["NL", /([A-Z0-9\*\+]{10}\d{2})$/]);            //** Netherlands sole proprietor
     vatexp.push (["NO", /(\d{9})$/]);                            // ** Norway (not EU)
     vatexp.push (["PL", /(\d{10})$/]);                           // ** Poland
     vatexp.push (["PT", /(\d{9})$/]);                            // ** Portugal
     vatexp.push (["RO", /([1-9]\d{1,9})$/]);                     // ** Romania
     vatexp.push (["RU", /(\d{10}|\d{12})$/]);                    // ** Russia
     vatexp.push (["RS", /(\d{9})$/]);                            // ** Serbia
     vatexp.push (["SI", /([1-9]\d{7})$/]);                       // ** Slovenia
     vatexp.push (["SK", /([1-9]\d[2346-9]\d{7})$/]);             // ** Slovakia Republic
     vatexp.push (["SE", /(\d{10}01)$/]);                         // ** Sweden
 
     // Error messages definition
     var mStrConLan = context.lang;

     var mStrMsgErr1 = {
          "ca": "Caràcters no vàlids",
          "de": "Ungültige Zeichen",
          "en": "Characters not valid",
          "es": "Caracteres no válidos",
          "fr": "Caractères non valides",
          "it": "Caratteri non validi",
          "pt": "Caracteres não válidos"
        };
      
      var mStrMsgErr2 = {
          "ca": "El prefix del passaport no és vàlid",
          "de": "Das Passportrückentext ist ungültig",
          "en": "Passport prefix not valid",
          "es": "El prefijo del pasaporte no es válido",
          "fr": "Le préfixe du passeport n'est pas valide",
          "it": "Il prefisso del passaporto non è valido",
          "pt": "O prefixo do passaporte não é válido"
        };
            
      var mStrMsgErr3 = {
          "ca": "Longitud incorrecta",
          "de": "Falsche Länge",
          "en": "Incorrect length",
          "es": "Longitud incorrecta",
          "fr": "Longueur incorrecte",
          "it": "Lunghezza errata",
          "pt": "Comprimento incorreto"        
        };
      
     // First control input field
     if (!/^[0-9A-Z]*$/.test(field)) {
        return mStrMsgErr1[mStrConLan];
         // throw new Error("Characters not valid"); // Esta definición muestra mensaje genérico, no el especificado
     }
 
     // Load up the string to check
     field = field.toUpperCase();
 
     // Remove spaces etc. from the VAT number to help validation
     field = field.replace (/(\s|-|\.)+/g, '');
 
     // Passport validation, the first three positions must be a character.
     if (mciftyp == 3) {
         let regpass = new RegExp("[A-Z][A-Z][A-Z]");
         if (regpass.test(field))
             return true;
         else
            return mStrMsgErr2[mStrConLan];
            // throw new Error("Passport prefix not valid"); // Esta definición muestra mensaje genérico, no el especificado
     }
 
     // Remove country code in NIF-UE intraCommunity operator
     if (mciftyp == 2) {
         field = field.substring(2);
         // http://ec.europa.eu/taxation_customs/vies/faqvies.do#item_11
         if ((mcifiss.match("FI|HU|LU|MT|SI")       && field.length !=  8) ||
             (mcifiss.match("AT|CY|DE|EE|EL|ES|PT") && field.length !=  9) ||
             (mcifiss.match("BE|PL|SK")             && field.length != 10) ||
             (mcifiss.match("HR|IT|LV")             && field.length != 11) ||
             (mcifiss.match("RO")                   && field.length  > 10) ||
             (mcifiss.match("NL|SE")                && field.length != 12))
              return getNumberFormatError(field, mcifiss)[mStrConLan]
             // throw new Error(`VAT number format ${field} with length ${field.length}
             //    not valid for ${mcifiss}`); // Esta definición muestra mensaje genérico, no el especificado
     }
 
     // Check the string against the regular expressions for all types of VAT numbers
     for (i=0; i < vatexp.length; i++) {
         if (vatexp[i][0] == mcifiss) {
             valid = false;
 
             // Have we recognised the VAT number?
             if (vatexp[i][1].test(field)) {
                 // Call the appropriate country VAT validation routine depending on the country code
                 // if (eval(mcifiss+"VATCheckDigit ('"+field+"')"))
                    // valid = true; // Esta definición muestra mensaje genérico, no el especificado
                  valid = eval(mcifiss+"VATCheckDigit ('"+field+"')");
 
                 // Having processed the number, we break from the loop
                 break;
             }
         }
     }
 
     // Return with either an error or the reformatted VAT number
     return valid;

 function getNumberFormatError(mStrField, mStrCifiss){
    return {
          "ca": `El format del número VAT ${mStrField} amb una longitud de ${mStrField.length} no és vàlid per ${mStrCifiss}`,
          "de": `Das VAT-Nummernformat ${mStrField} mit einer Länge von ${mStrField.length} ist nicht gültig für ${mStrCifiss}`,
          "en": `VAT number format ${mStrField} with length ${mStrField.length} not valid for ${mStrCifiss}`,
          "es": `El formato del número VAT ${mStrField} con longitud ${mStrField.length} no es válido para ${mStrCifiss}`,
          "fr": `Le format du numéro de TVA ${mStrField} avec une longueur de ${mStrField.length} n'est pas valide pour ${mStrCifiss}`,
          "it": `Il formato del numero VAT ${mStrField} con lunghezza ${mStrField.length} non è valido per ${mStrCifiss}`,
          "pt": `O formato do número VAT ${mStrField} com comprimento ${mStrField.length} não é válido para ${mStrCifiss}`
        };
 }

 function getControlLetterError(pStrNum, pStrLetCont, pIntType){
   // Personal number (NIF) (starting with numeric of Y or Z)
   if(pIntType == 1){
    pStrNum = pStrNum.substring(0,8);
    return {
          "ca": `Lletra de control incorrecta. Seria ${pStrNum}${pStrLetCont}`,
          "de": `Falscher Kontrollbuchstabe. Es wäre ${pStrNum}${pStrLetCont}`,
          "en": `Incorrect control letter. It would be ${pStrNum}${pStrLetCont}`,
          "es": `Letra de control incorrecta. Sería ${pStrNum}${pStrLetCont}`,
          "fr": `Lettre de contrôle incorrecte. Ce serait ${pStrNum}${pStrLetCont}`,
          "it": `Lettera di controllo errata. Sarebbe ${pStrNum}${pStrLetCont}`,
          "pt": `Letra de controle incorreta. Seria ${pStrNum}${pStrLetCont}`
        }
   }
   // Personal number (NIF) (starting with K, L, M, or X)
   else{
    pStrNum = pStrNum.substring(1,8);
    return {
          "ca": `Lletra de control incorrecta. Seria ${pStrNum}${pStrLetCont}`,
          "de": `Falscher Kontrollbuchstabe. Es wäre ${pStrNum}${pStrLetCont}`,
          "en": `Incorrect control letter. It would be ${pStrNum}${pStrLetCont}`,
          "es": `Letra de control incorrecta. Sería ${fpStrNum}${pStrLetCont}`,
          "fr": `Lettre de contrôle incorrecte. Ce serait ${pStrNum}${pStrLetCont}`,
          "it": `Lettera di controllo errata. Sarebbe ${pStrNum}${pStrLetCont}`,
          "pt": `Letra de controle incorreta. Seria ${pStrNum}${pStrLetCont}`
        }
   }
 }

 function ATVATCheckDigit (field) {
 
   // Checks the check digits of an Austrian VAT number.
   // There always be a U at the beginning
 
   var total = 0;
   var multipliers = [0,1,2,1,2,1,2,1];
   var temp = 0;
 
   // Extract the next digit and multiply by the appropriate multiplier.
   for (var i = 1; i < 8; i++) {
     temp = Number(field.charAt(i)) * multipliers[i];
     if (temp > 9)
       total += Math.floor(temp/10) + temp%10
     else
       total += temp;
   }
 
   // Establish check digit.
   total = 10 - (total+4) % 10;
   if (total == 10) total = 0;
 
   // Compare it with the last character of the VAT number. If it's the same, then it's valid.
   if (total == field.slice (8,9))
     return true
   else
     return false;
 }
 
 function BEVATCheckDigit (field) {
 
   // Checks the check digits of a Belgium VAT number.
 
   // Nine digit numbers have a 0 inserted at the front.
   if (field.length == 9) field = "0" + field;
 
   if (field.slice(1,2) == 0) return false;
 
   // Modulus 97 check on last nine digits
   if (97 - field.slice (0,8) % 97 == field.slice (8,10))
     return true
   else
     return false;
 }
 
 function BGVATCheckDigit (field) {
 
   // Checks the check digits of a Bulgarian VAT number.
 
   if (field.length == 9) {
 
     // Check the check digit of 9 digit Bulgarian VAT numbers.
     var total = 0;
 
     // First try to calculate the check digit using the first multipliers
     var temp = 0;
     for (var i = 0; i < 8; i++) temp += Number(field.charAt(i)) * (i+1);
 
     // See if we have a check digit yet
     total = temp % 11;
     if (total != 10) {
       if (total == field.slice (8))
         return true
       else
         return false;
     }
 
     // We got a modulus of 10 before so we have to keep going. Calculate the new check digit using
     // the different multipliers
     var temp = 0;
     for (var i = 0; i < 8; i++) temp += Number(field.charAt(i)) * (i+3);
 
     // See if we have a check digit yet. If we still have a modulus of 10, set it to 0.
     total = temp % 11;
     if (total == 10) total = 0;
     if (total == field.slice (8))
       return true
     else
       return false;
   }
 
   // 10 digit VAT code - see if it relates to a standard physical person
   if ((/^\d\d[0-5]\d[0-3]\d\d{4}$/).test(field)) {
 
     // Check month
     var month = Number(field.slice(2,4));
     if ((month > 0 && month < 13) || (month > 20 && month < 33) || (month > 40 && month < 53)) {
 
       // Extract the next digit and multiply by the counter.
       var multipliers = [2,4,8,5,10,9,7,3,6];
       var total = 0;
       for (var i = 0; i < 9; i++) total += Number(field.charAt(i)) * multipliers[i];
 
       // Establish check digit.
       total = total % 11;
       if (total == 10) total = 0;
 
       // Check to see if the check digit given is correct, If not, try next type of person
       if (total == field.substr (9,1)) return true;
     }
   }
 
   // It doesn't relate to a standard physical person - see if it relates to a foreigner.
 
   // Extract the next digit and multiply by the counter.
   var multipliers = [21,19,17,13,11,9,7,3,1];
   var total = 0;
   for (var i = 0; i < 9; i++) total += Number(field.charAt(i)) * multipliers[i];
 
   // Check to see if the check digit given is correct, If not, try next type of person
   if (total % 10 == field.substr (9,1)) return true;
 
   // Finally, if not yet identified, see if it conforms to a miscellaneous VAT number
 
   // Extract the next digit and multiply by the counter.
   var multipliers = [4,3,2,7,6,5,4,3,2];
   var total = 0;
   for (var i = 0; i < 9; i++) total += Number(field.charAt(i)) * multipliers[i];
 
   // Establish check digit.
   total = 11 - total % 11;
   if (total == 10) return false;
   if (total == 11) total = 0;
 
   // Check to see if the check digit given is correct, If not, we have an error with the VAT number
   if (total == field.substr (9,1))
     return true;
   else
     return false;
 }
 
 function CHVATCheckDigit (field) {
 
   // Checks the check digits of a Swiss VAT number.
 
   // Extract the next digit and multiply by the counter.
   var multipliers = [5,4,3,2,7,6,5,4];
   var total = 0;
   for (var i = 0; i < 8; i++) total += Number(field.charAt(i)) * multipliers[i];
 
   // Establish check digit.
   total = 11 - total % 11;
   if (total == 10) return false;
   if (total == 11) total = 0;
 
   // Check to see if the check digit given is correct, If not, we have an error with the VAT number
   if (total == field.substr (8,1))
     return true;
   else
     return false;
 }
 
 function CYVATCheckDigit (field) {
 
   // Checks the check digits of a Cypriot VAT number.
 
   // Not allowed to start with '12'
   if (Number(field.slice(0,2) == 12)) return false;
 
   // Extract the next digit and multiply by the counter.
   var total = 0;
   for (var i = 0; i < 8; i++) {
     var temp = Number(field.charAt(i));
     if (i % 2 == 0) {
       switch (temp) {
